1	@import 'tailwindcss';
2	
3	@theme {
4	    /* DEFAULT COLORS */
5	    --color-inherit: inherit;
6	    --color-current: currentcolor;
7	    --color-transparent: transparent;
8	    --color-black: #000;
9	    --color-white: #fff;
10	
11	    /* CUSTOM COLORS */
12	    --color-primary-lighter-1: #3f3fe4;
13	    --color-primary-lighter-2: #6c6cea;
14	    --color-primary-lighter-3: #9898f0;
15	    --color-primary: #1e1ed2;
16	    --color-primary-darker-1: #1818a5;
17	    --color-primary-darker-2: #111178;
18	
19	    --color-secondary-lighter-1: #ee6da3;
20	    --color-secondary-lighter-2: #f39bc0;
21	    --color-secondary-lighter-3: #f9c8dd;
22	    --color-secondary: #e94187;
23	    --color-secondary-darker-1: #db1a6b;
24	    --color-secondary-darker-2: #ad1455;
25	
26	    --color-gray-1: #2a363a;
27	    --color-gray-2: #5a666b;
28	    --color-gray-3: #859095;
29	    --color-gray-4: #a5aeb2;
30	    --color-gray-5: #d3d8da;
31	    --color-gray-6: #edeff0;
32	    --color-gray-7: #fdfdfd;
33	
34	    --color-success-lighter-1: #6ceab5;
35	    --color-success-lighter-2: #c5f7e2;
36	    --color-success: #1ed286;
37	
38	    --color-error-lighter-1: #ea7b6c;
39	    --color-error-lighter-2: #f7cbc5;
40	    --color-error: #d2341e;
41	
42	    --color-warning-lighter-1: #fed69a;
43	    --color-warning-lighter-2: #ffebcc;
44	    --color-warning: #fdae37;
45	
46	    --color-info-info-lighter-1: #aad3f8;
47	    --color-info-info-lighter-2: #d9ebfc;
48	    --color-info: #4da2f0;
49	
50	    /* FONT SIZES */
51	    --text-micro: 11px;
52	    --text-micro--line-height: 16px;
53	    --text-tiny: 12px;
54	    --text-tiny--line-height: 16px;
55	    --text-small: 14px;
56	    --text-small--line-height: 20px;
57	    --text-base: 16px;
58	    --text-base--line-height: 24px;
59	    --text-medium: 20px;
60	    --text-medium--line-height: 28px;
61	    --text-large: 24px;
62	    --text-large--line-height: 32px;
63	    --text-xlarge: 32px;
64	    --text-xlarge--line-height: 40px;
65	    --text-2xlarge: 40px;
66	    --text-2xlarge--line-height: 48px;
67	    --text-3xlarge: 48px;
68	    --text-3xlarge--line-height: 56px;
69	    --text-4xlarge: 60px;
70	    --text-4xlarge--line-height: 72px;
71	
72	    /* SPACINGS */
73	    --spacing-0: 0px;
74	    --spacing-1: 1px;
75	    --spacing-2: 2px;
76	    --spacing-3: 3px;
77	    --spacing-4: 4px;
78	    --spacing-5: 5px;
79	    --spacing-6: 6px;
80	    --spacing-7: 7px;
81	    --spacing-8: 8px;
82	    --spacing-9: 9px;
83	    --spacing-10: 10px;
84	    --spacing-11: 11px;
85	    --spacing-12: 12px;
86	    --spacing-14: 14px;
87	    --spacing-16: 16px;
88	    --spacing-20: 20px;
89	    --spacing-24: 24px;
90	    --spacing-28: 28px;
91	    --spacing-32: 32px;
92	    --spacing-36: 36px;
93	    --spacing-40: 40px;
94	    --spacing-44: 44px;
95	    --spacing-48: 48px;
96	    --spacing-52: 52px;
97	    --spacing-56: 56px;
98	    --spacing-60: 60px;
99	    --spacing-64: 64px;
100	    --spacing-72: 72px;
101	    --spacing-80: 80px;
102	    --spacing-96: 96px;
103	    --spacing-100: 100px;
104	    --spacing-px: 1px;
105	    --spacing-0_5: 0.5px;
106	    --spacing-1_5: 1.5px;
107	    --spacing-2_5: 2.5px;
108	    --spacing-3_5: 3.5px;
109	}
110	
111	/*
112	  The default border color has changed to `currentcolor` in Tailwind CSS v4,
113	  so we've added these compatibility styles to make sure everything still
114	  looks the same as it did with Tailwind CSS v3.
115	
116	  If we ever want to remove these styles, we need to add an explicit border
117	  color utility to any element that depends on these defaults.
118	*/
119	@layer base {
120	    *,
121	    ::after,
122	    ::before,
123	    ::backdrop,
124	    ::file-selector-button {
125	        border-color: var(--color-gray-200, currentcolor);
126	        -webkit-font-smoothing: antialiased;
127	        -moz-osx-font-smoothing: grayscale;
128	    }
129	
130	    /** This is by default set as font: inherit, which sets button to root font size, or 16px. When size is not explicitly set, button font size won't be the same in all buttons. */
131	    button {
132	        @apply text-small;
133	    }
134	
135	    a {
136	        @apply text-primary underline;
137	    }
138	
139	    body {
140	        @apply bg-gray-6;
141	    }
142	
143	    code {
144	        @apply bg-gray-5 rounded-md px-4 py-2;
145	    }
146	}
