1	/* ============================================================
2	   HIDROING — design system
3	   ============================================================ */
4	
5	:root {
6	  --ink: #0D0F0E;
7	  --ink-2: #2B2F2D;
8	  --ink-3: #5C635F;
9	  --ink-4: #9BA19D;
10	  --rule: #D9DCD8;
11	  --rule-2: #E8EAE6;
12	  --paper: #F6F7F5;
13	  --paper-2: #EDEFEA;
14	  --white: #FFFFFF;
15	
16	  --green: oklch(0.62 0.17 155);
17	  --green-ink: oklch(0.38 0.12 155);
18	  --blue: oklch(0.45 0.16 235);
19	  --blue-ink: oklch(0.28 0.12 235);
20	
21	  --sans: var(--font-inter-tight, "Inter Tight", "Helvetica Neue", Helvetica, Arial, sans-serif);
22	  --mono: var(--font-jetbrains-mono, "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace);
23	
24	  --pad-x: clamp(20px, 4vw, 64px);
25	  --pad-y: clamp(56px, 9vw, 140px);
26	  --max: 1440px;
27	}
28	
29	/* Reset Tailwind base conflicts */
30	html, body {
31	  margin: 0;
32	  padding: 0;
33	  background: var(--paper);
34	  color: var(--ink);
35	  font-family: var(--sans);
36	  font-feature-settings: "ss01", "cv11", "tnum";
37	  -webkit-font-smoothing: antialiased;
38	  text-rendering: optimizeLegibility;
39	  font-size: 16px;
40	  line-height: 1.5;
41	}
42	
43	img { display: block; max-width: 100%; }
44	
45	a {
46	  color: inherit;
47	  text-decoration: none;
48	}
49	
50	/* Typography scale */
51	.display {
52	  font-family: var(--sans);
53	  font-weight: 500;
54	  letter-spacing: -0.03em;
55	  line-height: 0.98;
56	  font-size: clamp(48px, 8vw, 132px);
57	  text-wrap: balance;
58	}
59	.h1 {
60	  font-weight: 500;
61	  letter-spacing: -0.025em;
62	  line-height: 1.02;
63	  font-size: clamp(40px, 5.4vw, 88px);
64	  text-wrap: balance;
65	  margin: 0;
66	}
67	.h2 {
68	  font-weight: 500;
69	  letter-spacing: -0.02em;
70	  line-height: 1.05;
71	  font-size: clamp(28px, 3.2vw, 48px);
72	  text-wrap: balance;
73	  margin: 0;
74	}
75	.h3 {
76	  font-weight: 500;
77	  letter-spacing: -0.01em;
78	  line-height: 1.15;
79	  font-size: clamp(20px, 1.8vw, 26px);
80	  margin: 0;
81	}
82	.body-lg {
83	  font-size: clamp(18px, 1.4vw, 22px);
84	  line-height: 1.5;
85	  letter-spacing: -0.005em;
86	  color: var(--ink-2);
87	  text-wrap: pretty;
88	}
89	.body {
90	  font-size: 16px;
91	  line-height: 1.6;
92	  color: var(--ink-2);
93	  text-wrap: pretty;
94	}
95	.small {
96	  font-size: 13px;
97	  line-height: 1.5;
98	  color: var(--ink-3);
99	}
100	
101	.eyebrow {
102	  font-family: var(--mono);
103	  font-size: 11px;
104	  letter-spacing: 0.1em;
105	  text-transform: uppercase;
106	  color: var(--ink-3);
107	  font-weight: 500;
108	}
109	.eyebrow .dot {
110	  display: inline-block;
111	  width: 6px; height: 6px;
112	  border-radius: 50%;
113	  background: var(--green);
114	  margin-right: 10px;
115	  transform: translateY(-1px);
116	}
117	.eyebrow.blue .dot { background: var(--blue); }
118	
119	.num {
120	  font-family: var(--mono);
121	  font-variant-numeric: tabular-nums;
122	  font-weight: 500;
123	}
124	
125	/* Layout primitives */
126	.wrap {
127	  max-width: var(--max);
128	  margin: 0 auto;
129	  padding-left: var(--pad-x);
130	  padding-right: var(--pad-x);
131	}
132	.section { padding-top: var(--pad-y); padding-bottom: var(--pad-y); }
133	.section--tight { padding-top: calc(var(--pad-y) * 0.6); padding-bottom: calc(var(--pad-y) * 0.6); }
134	.rule {
135	  height: 1px; background: var(--rule);
136	  width: 100%;
137	}
138	
139	/* Nav */
140	.nav {
141	  position: sticky;
142	  top: 0;
143	  z-index: 50;
144	  background: color-mix(in oklab, var(--paper) 85%, transparent);
145	  backdrop-filter: saturate(140%) blur(8px);
146	  -webkit-backdrop-filter: saturate(140%) blur(8px);
147	  border-bottom: 1px solid var(--rule);
148	}
149	.nav__inner {
150	  max-width: var(--max);
151	  margin: 0 auto;
152	  padding: 18px var(--pad-x);
153	  display: flex;
154	  align-items: center;
155	  justify-content: space-between;
156	  gap: 32px;
157	}
158	.nav__logo { display: flex; align-items: center; gap: 10px; }
159	.nav__logo img { height: 34px; width: auto; }
160	.nav__links {
161	  display: flex;
162	  align-items: center;
163	  gap: 32px;
164	  font-size: 14px;
165	  font-weight: 500;
166	  letter-spacing: -0.01em;
167	}
168	.nav__links a {
169	  color: var(--ink-2);
170	  position: relative;
171	  padding: 6px 0;
172	  transition: color .15s ease;
173	}
174	.nav__links a:hover { color: var(--ink); }
175	.nav__links a.active { color: var(--ink); }
176	.nav__links a.active::after {
177	  content: "";
178	  position: absolute; left: 0; right: 0; bottom: -2px;
179	  height: 1px; background: var(--green);
180	}
181	.nav__right {
182	  display: flex;
183	  align-items: center;
184	  gap: 18px;
185	}
186	.lang-toggle {
187	  display: inline-flex;
188	  align-items: center;
189	  gap: 0;
190	  font-family: var(--mono);
191	  font-size: 11px;
192	  letter-spacing: 0.08em;
193	  border: 1px solid var(--rule);
194	  border-radius: 999px;
195	  padding: 3px;
196	  background: var(--white);
197	}
198	.lang-toggle button {
199	  border: 0; background: transparent;
200	  padding: 5px 10px;
201	  border-radius: 999px;
202	  font: inherit;
203	  letter-spacing: inherit;
204	  color: var(--ink-3);
205	  cursor: pointer;
206	}
207	.lang-toggle button.active {
208	  background: var(--ink);
209	  color: var(--paper);
210	}
211	
212	/* Buttons */
213	.btn {
214	  display: inline-flex;
215	  align-items: center;
216	  gap: 10px;
217	  padding: 14px 22px;
218	  border-radius: 999px;
219	  font-weight: 500;
220	  font-size: 14px;
221	  letter-spacing: -0.01em;
222	  border: 1px solid var(--ink);
223	  background: var(--ink);
224	  color: var(--paper);
225	  cursor: pointer;
226	  transition: transform .15s ease, background .15s ease, color .15s ease;
227	  font-family: var(--sans);
228	}
229	.btn:hover { background: var(--green-ink); border-color: var(--green-ink); }
230	.btn--ghost { background: transparent; color: var(--ink); }
231	.btn--ghost:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
232	.btn .arrow {
233	  display: inline-block;
234	  width: 14px; height: 1px; background: currentColor; position: relative;
235	}
236	.btn .arrow::after {
237	  content: ""; position: absolute; right: 0; top: -3px;
238	  width: 7px; height: 7px;
239	  border-right: 1px solid currentColor;
240	  border-top: 1px solid currentColor;
241	  transform: rotate(45deg);
242	}
243	
244	.chip {
245	  display: inline-flex;
246	  align-items: center;
247	  gap: 8px;
248	  padding: 6px 12px;
249	  border-radius: 999px;
250	  background: var(--white);
251	  border: 1px solid var(--rule);
252	  font-size: 12px;
253	  color: var(--ink-2);
254	  font-weight: 500;
255	}
256	
257	/* Placeholder imagery */
258	.ph {
259	  position: relative;
260	  background:
261	    repeating-linear-gradient(
262	      135deg,
263	      rgba(13,15,14,0.035) 0 1px,
264	      transparent 1px 9px
265	    ),
266	    linear-gradient(180deg, #E4E7E1 0%, #D4D8D1 100%);
267	  overflow: hidden;
268	  border-radius: 2px;
269	}
270	.ph--blue {
271	  background:
272	    repeating-linear-gradient(
273	      135deg,
274	      rgba(13,15,14,0.045) 0 1px,
275	      transparent 1px 9px
276	    ),
277	    linear-gradient(180deg, oklch(0.78 0.05 235) 0%, oklch(0.55 0.11 235) 100%);
278	}
279	.ph--green {
280	  background:
281	    repeating-linear-gradient(
282	      135deg,
283	      rgba(13,15,14,0.045) 0 1px,
284	      transparent 1px 9px
285	    ),
286	    linear-gradient(180deg, oklch(0.78 0.07 155) 0%, oklch(0.5 0.12 155) 100%);
287	}
288	.ph--dark {
289	  background:
290	    repeating-linear-gradient(
291	      135deg,
292	      rgba(255,255,255,0.04) 0 1px,
293	      transparent 1px 9px
294	    ),
295	    linear-gradient(180deg, #2A2E2C 0%, #14171A 100%);
296	}
297	.ph__label {
298	  position: absolute;
299	  left: 14px;
300	  bottom: 14px;
301	  font-family: var(--mono);
302	  font-size: 10px;
303	  letter-spacing: 0.06em;
304	  color: rgba(13,15,14,0.6);
305	  text-transform: uppercase;
306	  padding: 4px 8px;
307	  background: rgba(246,247,245,0.7);
308	  backdrop-filter: blur(4px);
309	  border-radius: 2px;
310	}
311	.ph--blue .ph__label,
312	.ph--green .ph__label,
313	.ph--dark .ph__label {
314	  color: rgba(255,255,255,0.88);
315	  background: rgba(0,0,0,0.28);
316	}
317	.ph__corner {
318	  position: absolute;
319	  top: 12px; right: 12px;
320	  font-family: var(--mono);
321	  font-size: 10px;
322	  letter-spacing: 0.05em;
323	  color: rgba(13,15,14,0.55);
324	}
325	.ph--blue .ph__corner,
326	.ph--green .ph__corner,
327	.ph--dark .ph__corner { color: rgba(255,255,255,0.7); }
328	
329	/* Footer */
330	.footer {
331	  background: #0D0F0E;
332	  color: #C9CDC9;
333	}
334	.footer a { color: #C9CDC9; }
335	.footer a:hover { color: #fff; }
336	.footer__top {
337	  max-width: var(--max);
338	  margin: 0 auto;
339	  padding: 80px var(--pad-x) 48px;
340	  display: grid;
341	  grid-template-columns: 1.5fr 1fr 1fr 1fr;
342	  gap: 48px;
343	}
344	.footer__bottom {
345	  border-top: 1px solid #222523;
346	  max-width: var(--max);
347	  margin: 0 auto;
348	  padding: 24px var(--pad-x);
349	  display: flex;
350	  justify-content: space-between;
351	  align-items: center;
352	  font-size: 12px;
353	  color: #7A807C;
354	  font-family: var(--mono);
355	  letter-spacing: 0.04em;
356	}
357	.footer h4 {
358	  font-size: 11px;
359	  font-family: var(--mono);
360	  text-transform: uppercase;
361	  letter-spacing: 0.1em;
362	  color: #7A807C;
363	  font-weight: 500;
364	  margin: 0 0 18px;
365	}
366	.footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; font-size: 14px; }
367	.footer__brand p {
368	  margin: 18px 0 0;
369	  max-width: 34ch;
370	  color: #9BA19D;
371	  font-size: 14px;
372	  line-height: 1.55;
373	}
374	.footer__wordmark {
375	  font-weight: 500;
376	  letter-spacing: -0.02em;
377	  font-size: 28px;
378	  color: #fff;
379	}
380	.footer__wordmark .dot { color: var(--green); }
381	
382	/* Page chrome */
383	.page-hero {
384	  padding-top: clamp(80px, 10vw, 140px);
385	  padding-bottom: clamp(48px, 6vw, 80px);
386	  border-bottom: 1px solid var(--rule);
387	}
388	.page-hero .crumbs {
389	  font-family: var(--mono);
390	  font-size: 11px;
391	  letter-spacing: 0.08em;
392	  text-transform: uppercase;
393	  color: var(--ink-3);
394	  margin-bottom: 20px;
395	  display: flex;
396	  gap: 10px;
397	  align-items: center;
398	}
399	.page-hero .crumbs span.sep { opacity: .5; }
400	
401	/* Grid helpers */
402	.col-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }
403	.col-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
404	.col-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
405	
406	@media (max-width: 960px) {
407	  .col-2, .col-3, .col-4 { grid-template-columns: 1fr; }
408	  .footer__top { grid-template-columns: 1fr 1fr; }
409	  .nav__links { display: none; }
410	}
411	
412	/* Marquee */
413	.marquee-rule {
414	  display: flex;
415	  gap: 24px;
416	  align-items: center;
417	  font-family: var(--mono);
418	  font-size: 11px;
419	  letter-spacing: 0.1em;
420	  color: var(--ink-3);
421	  text-transform: uppercase;
422	  padding: 18px 0;
423	  border-top: 1px solid var(--rule);
424	  border-bottom: 1px solid var(--rule);
425	  overflow: hidden;
426	  white-space: nowrap;
427	}
428	.marquee-rule .item { display: inline-flex; align-items: center; gap: 12px; flex-shrink: 0; }
429	.marquee-rule .item::before {
430	  content: "";
431	  width: 4px; height: 4px;
432	  border-radius: 50%;
433	  background: var(--green);
434	  display: inline-block;
435	}
436	
437	@keyframes marquee {
438	  from { transform: translateX(0); }
439	  to { transform: translateX(-50%); }
440	}
441	.marquee-track {
442	  display: flex;
443	  gap: 24px;
444	  animation: marquee 24s linear infinite;
445	  width: max-content;
446	}
447	
448	/* Reveal on scroll */
449	.reveal { opacity: 0; transform: translateY(8px); transition: opacity .6s ease, transform .6s ease; }
450	.reveal.in { opacity: 1; transform: none; }
451	
452	/* Section heading */
453	.sec-head {
454	  display: grid;
455	  grid-template-columns: 200px 1fr 1fr;
456	  gap: 40px;
457	  align-items: baseline;
458	  margin-bottom: 56px;
459	}
460	.sec-head .num {
461	  font-family: var(--mono);
462	  font-size: 12px;
463	  color: var(--ink-3);
464	  letter-spacing: 0.08em;
465	}
466	.sec-head h2 { max-width: 18ch; }
467	.sec-head .lede { max-width: 42ch; color: var(--ink-2); font-size: 16px; line-height: 1.55; }
468	@media (max-width: 900px) {
469	  .sec-head { grid-template-columns: 1fr; gap: 16px; margin-bottom: 32px; }
470	}
471	
472	/* ===== Home page ===== */
473	.hero {
474	  padding-top: clamp(60px, 8vw, 120px);
475	  padding-bottom: clamp(40px, 6vw, 80px);
476	}
477	.hero__meta {
478	  display: flex;
479	  justify-content: space-between;
480	  align-items: center;
481	  gap: 24px;
482	  margin-bottom: 48px;
483	}
484	.hero__meta .meta-line {
485	  font-family: var(--mono);
486	  font-size: 11px;
487	  letter-spacing: 0.08em;
488	  text-transform: uppercase;
489	  color: var(--ink-3);
490	}
491	.hero__title {
492	  font-weight: 500;
493	  letter-spacing: -0.035em;
494	  line-height: 0.95;
495	  font-size: clamp(56px, 10vw, 156px);
496	  margin: 0;
497	  text-wrap: balance;
498	}
