3	import { useTranslations, useLocale } from 'next-intl';
4	import { useParams } from 'next/navigation';
5	import { Link, usePathname, useRouter } from 'modules/i18n/utils/navigation';
6	import Image from 'next/image';
7	
8	const NAV_ITEMS = [
9	  { href: '/' as const, key: 'home' },
10	  { href: '/services' as const, key: 'services' },
11	  { href: '/projects' as const, key: 'projects' },
12	  { href: '/team' as const, key: 'team' },
13	  { href: '/about' as const, key: 'about' },
14	  { href: '/contact' as const, key: 'contact' },
15	] satisfies Array<{
16	  href: '/' | '/services' | '/projects' | '/team' | '/about' | '/contact';
17	  key: string;
18	}>;
19	
20	export function Nav() {
21	  const t = useTranslations('Nav');
22	  const locale = useLocale();
23	  const pathname = usePathname();
24	  const params = useParams();
25	  const router = useRouter();
26	
27	  function switchLocale(next: string) {
28	    const href = (
29	      params && Object.keys(params).length > 0 ? { pathname, params } : pathname
30	    ) as any;
31	    router.replace(href, { locale: next });
32	  }
33	
34	  function isActive(href: string) {
35	    if (href === '/') return pathname === '/';
36	    return pathname.startsWith(href);
37	  }
38	
39	  return (
40	    <header className="nav">
41	      <div className="nav__inner">
42	        <Link href="/" className="nav__logo" aria-label="Hidroing">
43	          <Image
44	            src="/images/hidroing.png"
45	            alt="Hidroing"
46	            width={100}
47	            height={100}
48	          />
49	        </Link>
50	
51	        <nav className="nav__links" aria-label="Primary">
52	          {NAV_ITEMS.map((item) => (
53	            <Link
54	              key={item.key}
55	              href={item.href}
56	              className={isActive(item.href) ? 'active' : ''}>
57	              {t(item.key)}
58	            </Link>
59	          ))}
60	        </nav>
61	
62	        <div className="nav__right">
63	          <div className="lang-toggle" role="group" aria-label="Language">
64	            <button
65	              onClick={() => switchLocale('hr')}
66	              className={locale === 'hr' ? 'active' : ''}>
67	              HR
68	            </button>
69	            <button
70	              onClick={() => switchLocale('en')}
71	              className={locale === 'en' ? 'active' : ''}>
72	              EN
73	            </button>
74	          </div>
75	        </div>
76	      </div>
77	    </header>
78	  );
79	}
