/* ============================================================
   HIDROING — runtime CSS (only what Tailwind cannot express)
   ============================================================ */

/* Runtime CSS variables (needed for color-mix, gradients, form focus) */
:root {
  --ink: #0D0F0E;
  --ink-2: #2B2F2D;
  --ink-3: #5C635F;
  --ink-4: #9BA19D;
  --rule: #D9DCD8;
  --rule-2: #E8EAE6;
  --paper: #F6F7F5;
  --paper-2: #EDEFEA;
  --white: #FFFFFF;

  --green: oklch(0.62 0.17 155);
  --green-ink: oklch(0.38 0.12 155);
  --blue: oklch(0.45 0.16 235);
  --blue-ink: oklch(0.28 0.12 235);

  --sans: var(--font-inter-tight, "Inter Tight", "Helvetica Neue", Helvetica, Arial, sans-serif);
  --mono: var(--font-jetbrains-mono, "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace);

  --pad-x: clamp(20px, 4vw, 64px);
  --pad-y: clamp(56px, 9vw, 140px);
  --max: 1440px;
}

/* Placeholder gradients (cannot be expressed in Tailwind) */
.ph {
  position: relative;
  background:
    repeating-linear-gradient(
      135deg,
      rgba(13,15,14,0.035) 0 1px,
      transparent 1px 9px
    ),
    linear-gradient(180deg, #E4E7E1 0%, #D4D8D1 100%);
  overflow: hidden;
  border-radius: 2px;
}
.ph--blue {
  background:
    repeating-linear-gradient(
      135deg,
      rgba(13,15,14,0.045) 0 1px,
      transparent 1px 9px
    ),
    linear-gradient(180deg, oklch(0.78 0.05 235) 0%, oklch(0.55 0.11 235) 100%);
}
.ph--green {
  background:
    repeating-linear-gradient(
      135deg,
      rgba(13,15,14,0.045) 0 1px,
      transparent 1px 9px
    ),
    linear-gradient(180deg, oklch(0.78 0.07 155) 0%, oklch(0.5 0.12 155) 100%);
}
.ph--dark {
  background:
    repeating-linear-gradient(
      135deg,
      rgba(255,255,255,0.04) 0 1px,
      transparent 1px 9px
    ),
    linear-gradient(180deg, #2A2E2C 0%, #14171A 100%);
}
.ph__label {
  position: absolute;
  left: 14px;
  bottom: 14px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  color: rgba(13,15,14,0.6);
  text-transform: uppercase;
  padding: 4px 8px;
  background: rgba(246,247,245,0.7);
  backdrop-filter: blur(4px);
  border-radius: 2px;
}
.ph--blue .ph__label,
.ph--green .ph__label,
.ph--dark .ph__label {
  color: rgba(255,255,255,0.88);
  background: rgba(0,0,0,0.28);
}
.ph__corner {
  position: absolute;
  top: 12px; right: 12px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.05em;
  color: rgba(13,15,14,0.55);
}
.ph--blue .ph__corner,
.ph--green .ph__corner,
.ph--dark .ph__corner { color: rgba(255,255,255,0.7); }

/* Scroll reveal */
.reveal { opacity: 0; transform: translateY(8px); transition: opacity .6s ease, transform .6s ease; }
.reveal.in { opacity: 1; transform: none; }

/* Marquee animation */
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.marquee-track {
  display: flex;
  gap: 24px;
  animation: marquee 24s linear infinite;
